  {centerTab==='parts'&&<><View style={op.hero}><View style={{flex:1}}><Text style={s.eyebrow}>CZĘŚĆ DO TEGO ZLECENIA</Text><Text style={op.title}>Zeskanuj kod. Dane uzupełnią się automatycznie.</Text><Text style={s.muted}>{[car.plate,car.make,car.model,car.engine_code||car.engine].filter(Boolean).join(' · ')} · numer OE potwierdź według VIN</Text></View><View style={op.scan}><TextInput value={newPart.barcode} onChangeText={barcode=>setNewPart({...newPart,barcode})} onSubmitEditing={()=>lookupOrderPart(newPart.barcode)} placeholder="EAN / UPC / GTIN" placeholderTextColor="#65717c" keyboardType="numeric" style={[s.input,{flex:1,minWidth:190}]}/><Button primary disabled={partLookupBusy} onPress={()=>lookupOrderPart(newPart.barcode)}>{partLookupBusy?'Szukam…':'Szukaj'}</Button><Button onPress={()=>setPartScanner(true)}>Skaner</Button></View></View>{!!partLookupMessage&&<View style={op.message}><Text style={s.badge}>{partLookupBusy?'WYSZUKIWANIE':'WYNIK'}</Text><Text style={s.desc}>{partLookupMessage}</Text></View>}<Section title="Dane części do zlecenia" action={newPart.barcode?<Button small onPress={()=>{setNewPart(emptyOrderPart());setPartLookupMessage('');partLookupRef.current=''}}>Wyczyść</Button>:null}>{!!newPart.lookup_source&&<View style={ps.source}><Text style={s.badge}>{newPart.lookup_source}</Text><Text style={s.muted}>Dane katalogowe wymagają potwierdzenia zgodności z autem.</Text>{!!newPart.lookup_url&&<Button small onPress={()=>Linking.openURL(newPart.lookup_url)}>Źródło ↗</Button>}</View>}<View style={s.form2}><Field label="Kod kreskowy" value={newPart.barcode} onChangeText={barcode=>setNewPart({...newPart,barcode})}/><Field label="Nazwa" value={newPart.name} onChangeText={name=>setNewPart({...newPart,name})}/><Field label="Marka / producent" value={newPart.brand} onChangeText={brand=>setNewPart({...newPart,brand})}/><Field label="Numer katalogowy" value={newPart.part_no} onChangeText={part_no=>setNewPart({...newPart,part_no})}/><Field label="Numer OE dla pojazdu" value={newPart.oe_number} onChangeText={oe_number=>setNewPart({...newPart,oe_number})}/><Field label="Ilość" value={newPart.qty} onChangeText={qty=>setNewPart({...newPart,qty})} keyboardType="numeric"/><Field label="Zakup" value={newPart.unit_cost} onChangeText={unit_cost=>setNewPart({...newPart,unit_cost})} keyboardType="numeric"/><Field label="Sprzedaż" value={newPart.unit_price} onChangeText={unit_price=>setNewPart({...newPart,unit_price})} keyboardType="numeric"/><Field label="Hurtownia" value={newPart.supplier} onChangeText={supplier=>setNewPart({...newPart,supplier})}/></View><Field label="Pasuje do — marki i modele" value={newPart.vehicle_fitment} onChangeText={vehicle_fitment=>setNewPart({...newPart,vehicle_fitment})} multiline/><Field label="Numery OE / zamienniki" value={newPart.cross_numbers} onChangeText={cross_numbers=>setNewPart({...newPart,cross_numbers})} multiline/><Button primary disabled={partLookupBusy} onPress={addPart}>Dodaj część do zlecenia</Button>{parts.map(x=><View key={x.cloud_id} style={s.row}><View style={{flex:1}}><Text style={s.rowTitle}>{x.payload.name}</Text><Text style={s.muted}>{[x.payload.brand,x.payload.part_no,x.payload.barcode].filter(Boolean).join(' · ')||'brak danych katalogowych'} · OE {x.payload.oe_number||'do uzupełnienia'} · {x.payload.qty||1} szt.</Text>{!!x.payload.vehicle_fitment&&<Text numberOfLines={2} style={ix.compatibility}>PASUJE DO  {x.payload.vehicle_fitment.replaceAll('\n',' · ')}</Text>}<Text style={s.muted}>{x.payload.supplier_name||x.payload.supplier||'hurtownia nieustalona'} · {money(x.payload.unit_price)}</Text></View><Pressable onPress={async()=>{const i=partStatuses.indexOf(x.payload.status||'DO_ZAMOWIENIA');await patch('job_part_orders',x.cloud_id,{status:partStatuses[Math.min(i+1,partStatuses.length-1)]});refresh()}}><Text style={s.badge}>{x.payload.status||'DO_ZAMOWIENIA'}</Text></Pressable><Button small danger onPress={()=>Alert.alert('Usuń część',`Usunąć "${x.payload.name}" z tego zlecenia?`,[{text:'Anuluj',style:'cancel'},{text:'Usuń',style:'destructive',onPress:async()=>{await remove('job_part_orders',x.cloud_id);refresh()}}])}>Usuń</Button></View>)}</Section><ProductScanner visible={partScanner} close={()=>setPartScanner(false)} accept={code=>{setPartScanner(false);setNewPart({...emptyOrderPart(),barcode:code});lookupOrderPart(code)}}/></>}
  {centerTab==='docs'&&<><Section title="Notatki i wydanie"><Field label="Przyjęcie" value={notes?.payload.intake_notes||''} onChangeText={x=>setNotes(notes?{...notes,payload:{...notes.payload,intake_notes:x}}:{cloud_id:'',payload:{intake_notes:x,qc_notes:'',release_notes:''}})} multiline voice/><Field label="QC" value={notes?.payload.qc_notes||''} onChangeText={x=>setNotes(notes?{...notes,payload:{...notes.payload,qc_notes:x}}:{cloud_id:'',payload:{intake_notes:'',qc_notes:x,release_notes:''}})} multiline voice/><Field label="Zalecenia przy wydaniu" value={notes?.payload.release_notes||''} onChangeText={x=>setNotes(notes?{...notes,payload:{...notes.payload,release_notes:x}}:{cloud_id:'',payload:{intake_notes:'',qc_notes:'',release_notes:x}})} multiline voice/><Button primary onPress={()=>ensureNotes(notes?.payload||{})}>Zapisz notatki</Button></Section><MediaPanel orderId={orderId} media={media} refresh={refresh}/><SignaturePanel orderId={orderId} signatures={signatures} refresh={refresh}/></>}
